const input = $input.first().json.body || $input.first().json;
const communityId = Number(input.communityId);
const billingMonth = String(input.billingMonth || '');
if (!Number.isInteger(communityId) || communityId <= 0) throw new Error('communityId must be a positive integer');
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(billingMonth)) throw new Error('billingMonth must use YYYY-MM format');
const meterIds = Array.isArray(input.meterIds) ? [...new Set(input.meterIds.map(Number).filter(id => Number.isInteger(id) && id > 0))] : [];
const approved = input.approved === true;
const token = String(input.apiToken || $env.MANA_API_TOKEN || '');
if (approved && !token) throw new Error('Set apiToken in the request or MANA_API_TOKEN in n8n before approving a sync');
return [{ json: { communityId, billingMonth, meterIds, approved, token, preview: { action: approved ? 'CLOSE_SELECTED_METERS_AND_SYNC_CFBOS' : 'PREVIEW_ONLY', selectedMeterCount: meterIds.length, requiresHumanApproval: !approved } } }];

const gate = $input.first().json;
const baseUrl = String($env.MANA_API_BASE_URL || 'http://host.docker.internal:8082/api').replace(/\/$/, '');
const headers = { Authorization: `Bearer ${gate.token}`, 'Content-Type': 'application/json' };
const closed = [];
for (const meterId of gate.meterIds) {
  const response = await fetch(`${baseUrl}/v1/iot/metering/billing/${meterId}/close-month?billingMonth=${encodeURIComponent(gate.billingMonth)}`, { method: 'POST', headers, body: '{}' });
  const text = await response.text();
  if (!response.ok) throw new Error(`Close billing failed for meter ${meterId} (${response.status}): ${text.slice(0, 500)}`);
  closed.push(text ? JSON.parse(text) : null);
}
const syncResponse = await fetch(`${baseUrl}/v1/iot/metering/billing/cfbos-sync/${gate.communityId}?billingMonth=${encodeURIComponent(gate.billingMonth)}`, { method: 'POST', headers, body: '{}' });
const syncText = await syncResponse.text();
if (!syncResponse.ok) throw new Error(`CFBOS sync failed (${syncResponse.status}): ${syncText.slice(0, 500)}`);
return [{ json: { status: 'success', action: 'SYNCED', communityId: gate.communityId, billingMonth: gate.billingMonth, closedCycles: closed, syncedCycles: syncText ? JSON.parse(syncText) : [] } }];
